# Domain Taxonomies
TAXONOMY = {
    "Ethno-Racial": ["indio", "indigena", "indigina", "indijena", "indijino", "indigino", "espanol", "espanola", "mestiza", "aucara", "punas", "ishua"],
    "Legitimacy": ["legitimo", "legitima", "natural", "espurio", "espuria", "hijo", "hija"],
    "Geographic": ["pampamarca", "chacralla"]
}

# Legal Abbreviations Mapping
ABBREVIATIONS = {
    "hn": "hijo natural",
    "hl": "hijo legitimo",
    "id": "indigena",
    "indo": "indio"
}

def normalize_term(term):
    """Normalizes a term based on abbreviations, fuzzy matching, and taxonomy."""
    term = term.lower().strip().replace(".", "")

    # 1. Resolve Abbreviations
    if term in ABBREVIATIONS:
        return ABBREVIATIONS[term]

    # 2. Fuzzy Match against Taxonomy (handling scribal errors like 'indijena')
    for category, terms in TAXONOMY.items():
        matches = get_close_matches(term, terms, n=1, cutoff=0.7)
        if matches:
            return matches[0]

    return term

def parse_clusters(data):
    clusters = {}
    lines = [line for line in data.strip().split('\n') if line]

    for line in lines:
        cluster_id = line.split(':')[0].strip()
        terms_raw = line.split(':')[1].split(',')

        normalized_terms = []
        for raw in terms_raw:
            norm = normalize_term(raw)
            normalized_terms.append(norm)

        clusters[cluster_id] = normalized_terms

    return clusters

def structure_data(clusters):
    structured_output = {}

    for cid, terms in clusters.items():
        # Extract unique normalized terms
        unique_terms = list(set(terms))

        # Classify into facets
        facets = {
            "Ethno-Racial": [],
            "Legitimacy": [],
            "Geographic": []
        }

        for t in unique_terms:
            # Check if term belongs to any category
            for category, taxonomy_list in TAXONOMY.items():
                if t in taxonomy_list:
                    facets[category].append(t)
                    break
            # Handle multi-word terms (e.g., "hijo natural")
            if "hijo" in t or "hija" in t:
                if "natural" in t: facets["Legitimacy"].append("hijo natural")
                if "legitimo" in t: facets["Legitimacy"].append("hijo legitimo")
                if "espurio" in t: facets["Legitimacy"].append("hijo espurio")

        structured_output[cid] = {
            "normalized_terms": unique_terms,
            "facets": {k: list(set(v)) for k, v in facets.items()}
        }

    return structured_output

if __name__ == "__main__":
    parsed_clusters = parse_clusters(log_data)
    final_json = structure_data(parsed_clusters)
    print(json.dumps(final_json, indent=4, ensure_ascii=False))
